import{_ as t,c as a,o,ag as i}from"./chunks/framework.CQuhCYrb.js";const d=JSON.parse('{"title":"Sock Puppet Accounts","description":"","frontmatter":{"title":"Sock Puppet Accounts"},"headers":[],"relativePath":"general/sock-puppet-accounts.md","filePath":"general/sock-puppet-accounts.md","lastUpdated":null}'),n={name:"general/sock-puppet-accounts.md"};function r(s,e,c,l,p,u){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="sock-puppet-accounts" tabindex="-1">Sock Puppet Accounts <a class="header-anchor" href="#sock-puppet-accounts" aria-label="Permalink to &quot;Sock Puppet Accounts&quot;">​</a></h1><h2 id="sockpuppet-accounts-for-red-teaming-and-research" tabindex="-1">Sockpuppet Accounts for Red Teaming and Research <a class="header-anchor" href="#sockpuppet-accounts-for-red-teaming-and-research" aria-label="Permalink to &quot;Sockpuppet Accounts for Red Teaming and Research&quot;">​</a></h2><p>Sockpuppet accounts are fictitious profiles created on various digital platforms, primarily used for red teaming, civilian Open Source Research (OSR), and research purposes. These accounts simulate attacker behaviors, gather information without revealing the researcher’s identity, or verify system vulnerabilities.</p><p>This page holds only publicly available information with no connection to any organization.</p><h3 id="ethical-and-legal-considerations" tabindex="-1">Ethical and Legal Considerations <a class="header-anchor" href="#ethical-and-legal-considerations" aria-label="Permalink to &quot;Ethical and Legal Considerations&quot;">​</a></h3><ul><li><p><strong>Authorization</strong>: Ensure all activities using sockpuppet accounts are authorized by all stakeholders and are within legal and ethical boundaries.</p></li><li><p><strong>Transparency</strong>: Use sockpuppets only in scenarios where deception is legally and ethically justifiable and necessary for the outcome of the research or red team exercise.</p></li><li><p><strong>Data Protection</strong>: Handle any data collected through these accounts responsibly in accordance with applicable privacy laws and regulations.</p></li><li><p><strong>Terms of Service</strong>: Review and comply with the Terms of Service of any platform used to host sockpuppet accounts. Breaching these terms can lead to account suspension and legal repercussions.</p></li></ul><h3 id="community-guides" tabindex="-1">Community Guides <a class="header-anchor" href="#community-guides" aria-label="Permalink to &quot;Community Guides&quot;">​</a></h3><ul><li>JC The Elder created the <a href="/general/sock-puppet-accounts-creation.html">Puppet Creation Outline</a>, which works best when opened using Obsidian.</li></ul><h3 id="setting-up-the-environment" tabindex="-1">Setting Up the Environment <a class="header-anchor" href="#setting-up-the-environment" aria-label="Permalink to &quot;Setting Up the Environment&quot;">​</a></h3><ul><li><p><strong>Dedicated Devices</strong>: Use separate devices to manage sockpuppet accounts to avoid cross-contamination with personal or work devices.</p></li><li><p><strong>Virtual Machines</strong>: Set up virtual machines using software like VMware or VirtualBox for each sockpuppet to isolate their activities from your main operating system.</p></li><li><p><strong><a href="https://vm.irregularchat.com/" target="_blank" rel="noreferrer">KASM - Remote Virtual Environment</a></strong>: A self-hosted virtual environment for testing, limited to 5 users at a time.</p></li><li><p>See the <a href="/">server guide</a> for setting up your KASM instance.</p></li><li><p><strong>Secure Networks</strong>: Connect via VPNs or utilize networks not associated with your personal or work identities.</p></li></ul><h3 id="best-practices-for-sockpuppet-interaction" tabindex="-1">Best Practices for Sockpuppet Interaction <a class="header-anchor" href="#best-practices-for-sockpuppet-interaction" aria-label="Permalink to &quot;Best Practices for Sockpuppet Interaction&quot;">​</a></h3><ul><li><p><strong>Engagement</strong>: Interact consistent with the designed persona but avoid over-engagement that could lead to increased scrutiny.</p></li><li><p><strong>Documentation</strong>: Maintain thorough documentation of all engagements, noting the times, dates, nature of interaction, and any responses received.</p></li><li><p>See the <a href="/research/">section</a> for more information.</p></li></ul><h3 id="creating-sockpuppet-accounts" tabindex="-1">Creating Sockpuppet Accounts <a class="header-anchor" href="#creating-sockpuppet-accounts" aria-label="Permalink to &quot;Creating Sockpuppet Accounts&quot;">​</a></h3><h3 id="choosing-platforms" tabindex="-1">Choosing Platforms <a class="header-anchor" href="#choosing-platforms" aria-label="Permalink to &quot;Choosing Platforms&quot;">​</a></h3><ul><li>Determine which platforms are most relevant to your objectives. Common choices include social media networks, chat applications, dating applications, forums, and online communities.</li></ul><h3 id="account-creation" tabindex="-1">Account Creation <a class="header-anchor" href="#account-creation" aria-label="Permalink to &quot;Account Creation&quot;">​</a></h3><ul><li><p><strong>Email Addresses</strong>: Use separate email addresses to register each sockpuppet account. Services like <a href="https://simplelogin.io" target="_blank" rel="noreferrer">SimpleLogin</a> or <a href="https://addy.io" target="_blank" rel="noreferrer">Annonaddy</a> provide a level of obfuscation and security.</p></li><li><p><strong>Profile Details</strong>: Craft believable profiles with consistent details that fit the background and purpose of each sockpuppet.</p></li><li><p><strong>Paying for Services</strong>: Services like <a href="https://privacy.com" target="_blank" rel="noreferrer">Privacy.com</a> allow alias credit cards that can be limited and help maintain or obfuscate an account.</p></li></ul><h3 id="tools-for-managing-sockpuppets" tabindex="-1">Tools for Managing Sockpuppets <a class="header-anchor" href="#tools-for-managing-sockpuppets" aria-label="Permalink to &quot;Tools for Managing Sockpuppets&quot;">​</a></h3><ul><li><p><strong>Multi-Account Management Software</strong>: Tools like Multilogin or SessionBox can help manage multiple browser profiles securely.</p></li><li><p><strong><a href="https://storyforge.zenithflow.io" target="_blank" rel="noreferrer">StoryForge</a></strong>: Message creation tool based on your brand, audience, and goal. Can maintain your desired tone and shape messages around specific audiences.</p></li><li><p><strong>Virtual Private Networks (VPNs)</strong>: Use VPNs to mask the IP addresses associated with each account to prevent linkage of the accounts to each other or to the real user.</p></li><li><p><a href="/privacy/vpn-recommendation.html">Recommendations</a></p></li><li><p><strong><a href="/general/guide-to-password-managers.html">Managers</a></strong>: A vital tool for maintaining strong and unique credentials for multiple accounts.</p></li><li><p><strong><a href="https://simplelogin.io" target="_blank" rel="noreferrer">SimpleLogin</a></strong>: Tool for creating alias email addresses.</p></li><li><p><strong><a href="https://www.qubes-os.org/intro/" target="_blank" rel="noreferrer">QubesOS</a></strong>: Utilize QubesOS for a security-focused operating system that compartmentalizes each sockpuppet into separate, secure virtual machines.</p></li></ul><h3 id="operational-security-for-sockpuppets" tabindex="-1">Operational Security for Sockpuppets <a class="header-anchor" href="#operational-security-for-sockpuppets" aria-label="Permalink to &quot;Operational Security for Sockpuppets&quot;">​</a></h3><ul><li><p>See <a href="/general/dfp-guide.html">Guides</a> for detailed steps on fingerprinting mitigation.</p></li><li><p><strong>Browser Fingerprinting Mitigation</strong>: Use anti-fingerprinting tools like the Tor Browser or configure your browser settings to minimize fingerprintability.</p></li><li><p><strong>Consistent Story Maintenance</strong>: Regularly update sockpuppets’ background stories and interactions to maintain consistency and believability.</p></li></ul><h3 id="using-sockpuppet-accounts-in-red-teaming" tabindex="-1">Using Sockpuppet Accounts in Red Teaming <a class="header-anchor" href="#using-sockpuppet-accounts-in-red-teaming" aria-label="Permalink to &quot;Using Sockpuppet Accounts in Red Teaming&quot;">​</a></h3><ul><li><p>See <a href="/cybersecurity/cyber-red-teaming.html">Teaming page</a> for more details.</p></li><li><p><strong>Reconnaissance</strong>: Gather intelligence on targets using sockpuppets to simulate various outsider threats without revealing real identities.</p></li><li><p><strong>Phishing Campaigns</strong>: Use sockpuppets to conduct controlled phishing campaigns to assess the readiness of the target organization against social engineering attacks.</p></li></ul><h3 id="countermeasures-and-detection-prevention" tabindex="-1">Countermeasures and Detection Prevention <a class="header-anchor" href="#countermeasures-and-detection-prevention" aria-label="Permalink to &quot;Countermeasures and Detection Prevention&quot;">​</a></h3><ul><li><strong>Regularly Update Security Measures</strong>: Stay ahead of detection techniques by updating operational security measures and using the latest tools to protect sockpuppet anonymity.</li></ul><p>[Teaming] [Security] [Footprint] [and Techniques] [Required]</p>',26)])])}const g=t(n,[["render",r]]);export{d as __pageData,g as default};
